/* Transaction Form Modal Styles */

.modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(34, 30, 77, 0.28);
  z-index: 50;
  transition: opacity 0.23s;
}

.modal-content {
  background: var(--surface, #fff);
  border-radius: 14px;
  box-shadow: 0 4px 32px rgba(41,21,102,0.13);
  max-width: 400px;
  margin: 50px auto;
  padding: 32px 24px 17px 24px;
  position: relative;
  z-index: 51;
  animation: modalAppear 0.28s cubic-bezier(0.47,0,0.75,0.72);
}

@keyframes modalAppear {
  from {
    opacity: 0;
    transform: translateY(38px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Modal Close Button */
.modal-close-btn {
  position: absolute;
  top: 12px;
  right: 15px;
  background: none;
  border: none;
  font-size: 1.38em;
  cursor: pointer;
  color: var(--primary, #6C2EBE);
  opacity: 0.79;
  transition: opacity 0.19s;
}
.modal-close-btn:hover {
  opacity: 1;
  color: var(--expense, #E74C3C);
}

@media only screen and (max-width: 540px) {
  .modal-content {
    max-width: 98vw;
    margin: 7vw auto;
    padding: 19px 7vw 13px 7vw;
  }
